import {moveAccuracy,winPercent} from './accuracy-metric.js';
import {exactEvaluation,comparableEvaluations} from './evaluation-evidence.js';
import {UciLines} from './uci-lines.js';
export const TYPES={book:{label:'Teoria',icon:'▤',color:'#ab9676'},brilliant:{label:'Geniale',icon:'!!',color:'#32aaa1'},great:{label:'Grande mossa',icon:'!',color:'#548ac1'},best:{label:'Migliore',icon:'★',color:'#7a9a57'},excellent:{label:'Eccellente',icon:'✓',color:'#93aa6c'},good:{label:'Buona',icon:'•',color:'#a5ac8e'},inaccuracy:{label:'Imprecisione',icon:'?!',color:'#dfb94b'},mistake:{label:'Errore',icon:'?',color:'#e39648'},blunder:{label:'Grave errore',icon:'??',color:'#d56e60'},miss:{label:'Occasione mancata',icon:'↯',color:'#ca8b75'}};
export const chance=cp=>1/(1+Math.exp(-.00368208*Math.max(-10000,Math.min(10000,cp))));
export const accuracy=loss=>Math.max(0,Math.min(100,103.1668*Math.exp(-.04354*loss*100)-3.1669));
export function classify({before,after,side,uci,book,sacrifice=false,previousLoss=0}){const p=chance(before.cp*side),q=chance(after.cp*side),loss=Math.max(0,p-q),best=before.lines?.[0]?.pv[0]===uci;let type=loss<=.02?'excellent':loss<=.05?'good':loss<=.1?'inaccuracy':loss<=.2?'mistake':'blunder';if(best&&loss<=.02)type='best';if(comparableEvaluations(before,after,16)&&exactEvaluation(before.lines?.[1])&&best&&loss<=.02&&before.lines?.[1]&&before.lines[0].depth>=16&&before.lines[0].depth===before.lines[1].depth&&before.lines[0].pv?.[0]!==before.lines[1].pv?.[0]&&before.lines[0].mate==null&&before.lines[1].mate==null&&p-chance(before.lines[1].cp*side)>=.10)type='great';if(comparableEvaluations(before,after)&&best&&loss<=.02&&q>=.45&&sacrifice)type='brilliant';if(loss>=.1&&previousLoss>=.1&&p>=.6&&q<.6)type='miss';if(book&&loss<=.05&&after.mate==null)type='book';return{type,loss,accuracy:moveAccuracy(winPercent(before.cp*side),winPercent(after.cp*side)),before:p,after:q};}
export function terminal(chess){if(chess.isCheckmate())return{cp:chess.turn()==='w'?-100000:100000,mate:0,lines:[],terminal:'Scacco matto'};if(chess.isDraw())return{cp:0,mate:null,lines:[],terminal:'Patta'};return null}
export class Engine{constructor(onStatus){this.onStatus=onStatus;this.queue=Promise.resolve();this.cache=new Map();this.ready=null;this.worker=null;this.pending=null}init(){if(this.ready)return this.ready;this.onStatus('Caricamento di Stockfish…');this.ready=new Promise((resolve,reject)=>{let timer=setTimeout(()=>fail(new Error('Stockfish non si è avviato. Riprova con un browser aggiornato.')),45000);const fail=e=>{clearTimeout(timer);this.worker?.terminate();this.ready=null;reject(e)};try{this.worker=new Worker(new URL('./vendor/stockfish-19-lite-single.js',import.meta.url));this.worker.onerror=()=>{const e=new Error('Impossibile caricare Stockfish. Ricarica la pagina e riprova.');if(this.pending){this.pending.reject(e);this.pending=null}fail(e)};this.worker.onmessage=ev=>{for(const line of String(ev.data).split('\n')){if(line==='uciok'){this.worker.postMessage('setoption name Hash value 32');this.worker.postMessage('setoption name MultiPV value 2');this.worker.postMessage('isready')}if(line==='readyok'){clearTimeout(timer);this.onStatus('Stockfish 19 Lite · attivo');resolve()}if(this.pending)this.pending.line(line)}};this.worker.postMessage('uci')}catch(e){fail(e)}});return this.ready}
 evaluate(fen,quality='deep',searchmoves='',options={}){const key=JSON.stringify([fen,quality,searchmoves,options.skill??20,options.limits||null]);const useCache=(options.skill??20)===20;if(useCache&&this.cache.has(key))return Promise.resolve(this.cache.get(key));const task=async()=>{if(useCache&&this.cache.has(key))return this.cache.get(key);await this.init();return new Promise((resolve,reject)=>{const side=fen.split(' ')[1]==='w'?1:-1,collector=new UciLines(side);let timer=setTimeout(()=>{this.worker?.terminate();this.ready=null;this.pending=null;reject(new Error('Il motore ha impiegato troppo tempo. Riprova: la posizione è rimasta invariata.'))},30000);const finish=(v,err)=>{clearTimeout(timer);this.pending=null;err?reject(err):resolve(v)};this.pending={reject:e=>finish(null,e),line:line=>{collector.add(line);if(line.startsWith('bestmove')){const ordered=collector.finish();if(!ordered.length)finish(null,new Error('Il motore non ha restituito una valutazione.'));else finish({...ordered[0],lines:ordered,best:line.split(' ')[1],fen,search:{build:"stockfish-19-lite-single",quality,hashMiB:32,multiPV:2,limits:[...settings],skill:options.skill??20,searchmoves}})}}};this.worker.postMessage('setoption name Skill Level value '+(options.skill??20));this.worker.postMessage('setoption name MultiPV value 2');this.worker.postMessage('position fen '+fen);const settings=options.limits||{quick:[12,250],standard:[16,800],deep:[20,2200]}[quality];this.worker.postMessage(`go depth ${settings[0]} movetime ${settings[1]}${searchmoves?' searchmoves '+searchmoves:''}`)})};const p=this.queue.then(task).then(value=>{if(useCache){if(this.cache.size>=500)this.cache.delete(this.cache.keys().next().value);this.cache.set(key,value)}return value});this.queue=p.catch(()=>{});return p}}
